 IntPtr handle;int pid;long worldSlot,cachedEnemy,paramSlot;bool paramLocated;string paramError;NpcDamage damage=new NpcDamage();
 byte[] Read(long a,int n){if(a<0x10000||a>0x7FFFFFFFFFFF||n<0||n>100000000)throw new Exception("Invalid memory bounds.");byte[] b=new byte[n];IntPtr count;if(!ReadProcessMemory(handle,new IntPtr(a),b,n,out count)||count.ToInt64()!=n)throw new Exception("Game data unavailable during loading.");return b;}
 public static long Pointer(Func<long,int,byte[]> read,long a){long p=BitConverter.ToInt64(read(a,8),0);if(p<0x10000||p>0x7FFFFFFFFFFF)throw new Exception("Character data is not ready.");return p;}
 public static long FindInSet(long set,long target,Func<long,int,byte[]> read){int capacity=BitConverter.ToInt32(read(set+0x10,4),0);if(capacity<0||capacity>4096)throw new Exception("Character table capacity invalid.");if(capacity==0)return 0;long table=Pointer(read,set+0x18);byte[] entries=read(table,capacity*16);for(int i=0;i<capacity;i++){long actor=BitConverter.ToInt64(entries,i*16);if(actor<0x10000||actor>0x7FFFFFFFFFFF)continue;try{if(BitConverter.ToInt64(read(actor+8,8),0)==target){if(BitConverter.ToInt32(read(set+0x10,4),0)!=capacity||Pointer(read,set+0x18)!=table||BitConverter.ToInt64(read(table+i*16,8),0)!=actor)throw new Exception("Character table changed.");return actor;}}catch{}}return 0;}
 public static long FindSelectedTarget(long world,long target,Func<long,int,byte[]> read){return FindSelectedTarget(world,target,read,null);}
 public static long FindSelectedTarget(long world,long target,Func<long,int,byte[]> read,Action<string> diagnostic){uint selector=unchecked((uint)target);int container=(int)((selector>>20)&255),index=(int)(selector&0xFFFFF);if((selector>>28)!=1||container>=196)return 0;long slot=world+0x1DED8+container*8;long set=Pointer(read,slot);int capacity=BitConverter.ToInt32(read(set+0x10,4),0);if(capacity<=0||capacity>4096){if(diagnostic!=null)diagnostic("capacity="+capacity);return 0;}long table=Pointer(read,set+0x18),actor=0;bool direct=false;string detail="capacity="+capacity+", slot="+index; if(index<capacity){actor=BitConverter.ToInt64(read(table+index*16,8),0);if(actor>=0x10000&&actor<=0x7FFFFFFFFFFF){long found=BitConverter.ToInt64(read(actor+8,8),0);detail+=", actor handle=0x"+found.ToString("X16");if(found!=target)actor=0;else direct=true;}else{detail+=", empty entry";actor=0;}}else detail+=", index outside capacity";
 if(actor==0)try{actor=FindInSet(set,target,read);}catch(Exception ex){detail+=", set scan="+ex.Message;}
 if(actor==0){if(diagnostic!=null)diagnostic(detail);return 0;}
 if(Pointer(read,slot)!=set||Pointer(read,set+0x18)!=table||BitConverter.ToInt32(read(set+0x10,4),0)!=capacity||BitConverter.ToInt64(read(actor+8,8),0)!=target)return 0;
 // Direct-slot stability is checked only when this is the direct-slot actor.
