 public static long FindTarget(long world,long target,Func<long,int,byte[]> read){return FindTarget(world,target,read,null);}
 public static long FindTarget(long world,long target,Func<long,int,byte[]> read,Action<string> diagnostic){string indexed="no exact match";try{long actor=FindSelectedTarget(world,target,read,d=>indexed=d);if(actor!=0)return actor;}catch(Exception ex){indexed=ex.Message;}int readable=0,failed=0,populated=0;var visited=new HashSet<long>();for(int i=0;i<196;i++){try{long slot=world+0x1DED8+i*8,set=Pointer(read,slot);if(!visited.Add(set))continue;long actor=FindInSet(set,target,read);readable++;if(actor!=0&&Pointer(read,slot)==set)return actor;}catch{failed++;}}for(int i=0;i<192;i++){try{long set=world+0x470+i*0x160+0x78;if(BitConverter.ToInt32(read(set+0x10,4),0)>0)populated++;long actor=FindInSet(set,target,read);readable++;if(actor!=0)return actor;}catch{failed++;}}// Player, ghost, summon and debug ChrSets are inline, not pointers.
  for(int i=0;i<4;i++){try{long actor=FindInSet(world+0x10EE0+i*0x58,target,read);readable++;if(actor!=0)return actor;}catch{failed++;}}if(diagnostic!=null)diagnostic("selector set="+((unchecked((uint)target)>>20)&255)+", index="+(unchecked((uint)target)&0xFFFFF)+", indexed="+indexed+", populated="+populated+", tables="+readable+", invalid/unavailable="+failed+", target=0x"+target.ToString("X16"));return 0;
 }
 public static EnemySnapshot ReadEnemy(long actor,long target,Func<long,int,byte[]> read){if(BitConverter.ToInt64(read(actor+8,8),0)!=target)throw new Exception("Target changed.");int npc=BitConverter.ToInt32(read(actor+0x60,4),0);long modules=Pointer(read,actor+0x190),data=Pointer(read,modules);byte[] health=read(data+0x138,12);int hp=BitConverter.ToInt32(health,0),max=BitConverter.ToInt32(health,8);if(npc<0||hp<0||max<=0||hp>max||max>100000000)throw new Exception("Target health layout failed validation.");var result=new EnemySnapshot{NpcId=npc,Hp=hp,MaxHp=max,Handle=target};try{long resistance=Pointer(read,modules+0x20);byte[] b=read(resistance+0x10,56);var current=new int[7];var thresholds=new int[7];for(int i=0;i<7;i++){current[i]=BitConverter.ToInt32(b,i*4);thresholds[i]=BitConverter.ToInt32(b,28+i*4);if(current[i]<0||thresholds[i]<0||current[i]>10000000||thresholds[i]>10000000)throw new Exception();}result.Remaining=current;result.Thresholds=thresholds;}catch{result.Remaining=null;result.Thresholds=null;}
  try{long armor=Pointer(read,modules+0x40);byte[] meter=read(armor+0x10,8);float stance=BitConverter.ToSingle(meter,0),maxStance=BitConverter.ToSingle(meter,4);if(!float.IsNaN(stance)&&!float.IsInfinity(stance)&&!float.IsNaN(maxStance)&&!float.IsInfinity(maxStance)&&maxStance>0&&maxStance<=1000000&&stance>=0&&stance<=maxStance&&Pointer(read,modules+0x40)==armor){result.Stance=stance;result.MaxStance=maxStance;}}catch{}
  try{result.StatusBlocked=StatusSusceptibility.Read(actor,read);}catch(Exception ex){result.StatusError=ex.Message;}
  if(BitConverter.ToInt64(read(actor+8,8),0)!=target||Pointer(read,actor+0x190)!=modules||Pointer(read,modules)!=data||BitConverter.ToInt32(read(actor+0x60,4),0)!=npc)throw new Exception("Enemy changed during reading.");return result;
 }
 long Locate(Process process,byte?[] pattern,string label){var module=process.MainModule;byte[] file=File.ReadAllBytes(module.FileName);int pe=BitConverter.ToInt32(file,60),sections=BitConverter.ToUInt16(file,pe+6),optional=BitConverter.ToUInt16(file,pe+20),table=pe+24+optional;int matches=0;long slot=0;for(int s=0;s<sections;s++){int h=table+s*40;if(Encoding.ASCII.GetString(file,h,8).TrimEnd('\0')!=".text")continue;int size=BitConverter.ToInt32(file,h+8),rva=BitConverter.ToInt32(file,h+12);long start=module.BaseAddress.ToInt64()+rva;byte[] code=Read(start,size);for(int i=0;i<=code.Length-pattern.Length;i++){bool equal=true;for(int k=0;k<pattern.Length;k++)if(pattern[k].HasValue&&pattern[k].Value!=code[i+k]){equal=false;break;}if(equal){matches++;slot=start+i+7+BitConverter.ToInt32(code,i+3);}}}if(matches!=1)throw new Exception(label+" signature missing or ambiguous; unsupported game layout.");return slot;}
 public EnemySnapshot Poll(){foreach(string name in new[]{"EasyAntiCheat","EasyAntiCheat_EOS","start_protected_game"})if(Process.GetProcessesByName(name).Length>0)throw new Exception("Anti-cheat detected. Use this prototype only in your existing offline setup.");var games=Process.GetProcessesByName("eldenring");if(games.Length!=1)throw new Exception("Waiting for one Elden Ring process.");var p=games[0];string version=p.MainModule.FileVersionInfo.FileVersion;Version v;if(!Version.TryParse(version,out v)||!new[]{"1.8.0","1.8.1","1.9.0","1.9.1","2.0.0","2.0.1","2.2.0","2.2.3","2.3.0","2.4.0","2.5.0","2.6.0","2.6.1","2.6.2","2.7.0","2.7.1"}.Contains(v.Major+"."+v.Minor+"."+v.Build))throw new Exception("Unsupported game file version: "+version);handle=OpenProcess(0x410,false,p.Id);if(handle==IntPtr.Zero)throw new Exception("Read access denied.");try{if(pid!=p.Id||worldSlot==0){worldSlot=Locate(p,new byte?[]{0x48,0x8B,0x05,null,null,null,null,0x48,0x85,0xC0,0x74,0x0F,0x48,0x39,0x88},"WorldChrMan");pid=p.Id;cachedEnemy=0;paramSlot=0;paramLocated=false;damage.Reset();}long world=Pointer(Read,worldSlot),player=Pointer(Read,world+0x1E508),target=BitConverter.ToInt64(Read(player+0x6B0,8),0);if(target==0||target==-1||unchecked((uint)target)==uint.MaxValue){cachedEnemy=0;return null;}long actor=0;if(cachedEnemy!=0)try{if(BitConverter.ToInt64(Read(cachedEnemy+8,8),0)==target)actor=cachedEnemy;}catch{}string diagnostic="";if(actor==0)actor=FindTarget(world,target,Read,d=>diagnostic=d);if(actor==0)throw new Exception("Locked target unresolved · file version "+version+" · "+diagnostic);if(actor==player)return null;var result=ReadEnemy(actor,target,Read);try{if(!paramLocated){paramLocated=true;try{long rva;if(NpcDamage.Slots.TryGetValue(v.Major+"."+v.Minor+"."+v.Build,out rva))paramSlot=p.MainModule.BaseAddress.ToInt64()+rva;else paramSlot=Locate(p,new byte?[]{0x48,0x8B,0x0D,null,null,null,null,0x48,0x85,0xC9,0x0F,0x84,null,null,null,null,0x45,0x33,0xC0,0xBA,0x8E,0x00,0x00,0x00},"SoloParamRepository");}catch(Exception ex){paramError=ex.Message;}}if(paramSlot==0)throw new Exception(paramError??"NPC parameter repository unavailable.");result.Negation=damage.Read(paramSlot,result.NpcId,Read);result.BaseStatus=damage.BaseStatus;}catch(Exception ex){damage.Reset();result.DamageError=ex.Message;}if(Pointer(Read,worldSlot)!=world||Pointer(Read,world+0x1E508)!=player||BitConverter.ToInt64(Read(player+0x6B0,8),0)!=target)throw new Exception("Lock-on changed; refreshing.");cachedEnemy=actor;result.Version=version;return result;}finally{CloseHandle(handle);handle=IntPtr.Zero;}}
 public void Reset(){pid=0;worldSlot=0;cachedEnemy=0;paramSlot=0;paramLocated=false;damage.Reset();}
